import triton
import triton.language as tl
from triton.language.extra import libdevice

from flag_gems.runtime import get_tuned_config

_MODE_GENERAL = 0
_MODE_SQUARE = 1
_MODE_RSQRT = 2
_MODE_ONE = 3
_MODE_INT_ODD = 4
_MODE_INT_EVEN = 5
_MODE_TENSOR_EXP = 6

_AUTOTUNE_CONFIGS = get_tuned_config("iluvatar_float_power_tensor_scalar_candidate_0")


